package app.opentv

import com.google.common.truth.Truth.assertWithMessage
import java.io.File
import org.junit.Test

/**
 * The committed baseline profile (#148) is regenerated by hand on an emulator, never in CI, so
 * nothing else notices a run that broke partway and wrote a profile missing a journey. Each
 * journey the generator walks must leave its screen's code in the profile.
 */
class BaselineProfileTest {

    private val profile = File("src/main/generated/baselineProfiles/baseline-prof.txt")

    @Test
    fun `the profile covers each journey the generator walks`() {
        assertWithMessage("$profile is missing: see docs/PERFORMANCE.md to generate it")
            .that(profile.exists())
            .isTrue()
        val rules = profile.readLines()

        val journeys =
            mapOf(
                "cold start" to "Lapp/opentv/MainActivity;",
                "Home rows" to "Lapp/opentv/ui/HomeScreenKt;",
                "Live TV guide" to "Lapp/opentv/ui/channels/GuideGridKt;",
                "Movies and Shows grids" to "Lapp/opentv/ui/vod/VodScreensKt;",
                "details page" to "Lapp/opentv/ui/vod/VodDetailScreensKt;",
            )
        journeys.forEach { (journey, owner) ->
            assertWithMessage("no method of $owner in the profile, so the $journey journey didn't run")
                .that(rules.any { it.contains("$owner->") })
                .isTrue()
        }
    }
}
